import { test, expect, Page } from '@playwright/test';

test.describe('Checkout Flow - Sequential Async Steps', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('https://example-ecommerce.com');
  });

  test('should complete checkout steps in sequential order', async () => {
    // Step 1: Add item to cart
    await page.getByRole('button', { name: /add to cart/i }).first().click();
    await expect(page.getByText(/item added to cart/i)).toBeVisible();

    // Step 2: Navigate to cart
    await page.getByRole('link', { name: /view cart/i }).click();
    await expect(page.getByRole('heading', { name: /shopping cart/i })).toBeVisible();

    // Step 3: Proceed to checkout
    await page.getByRole('button', { name: /proceed to checkout/i }).click();
    await expect(page.getByRole('heading', { name: /checkout/i })).toBeVisible();

    // Step 4: Fill shipping information
    await page.getByLabel(/first name/i).fill('John');
    await page.getByLabel(/last name/i).fill('Doe');
    await page.getByLabel(/street address/i).fill('123 Main St');
    await page.getByLabel(/city/i).fill('New York');
    await page.getByLabel(/state/i).fill('NY');
    await page.getByLabel(/zip code/i).fill('10001');

    // Step 5: Select shipping method
    await page.getByRole('radio', { name: /standard shipping/i }).click();
    await expect(page.getByText(/shipping method selected/i)).toBeVisible();

    // Step 6: Fill payment information
    await page.getByLabel(/card number/i).fill('4111111111111111');
    await page.getByLabel(/expiration date/i).fill('12/25');
    await page.getByLabel(/cvv/i).fill('123');

    // Step 7: Review order
    await page.getByRole('button', { name: /review order/i }).click();
    await expect(page.getByRole('heading', { name: /order review/i })).toBeVisible();

    // Step 8: Confirm and place order
    await page.getByRole('button', { name: /place order/i }).click();

    // Wait for order confirmation
    await expect(page.getByRole('heading', { name: /order confirmed/i })).toBeVisible({ timeout: 10000 });
    await expect(page.getByText(/order number/i)).toBeVisible();
  });

  test('should handle async validation at each checkout step', async () => {
    // Add item to cart
    await page.getByRole('button', { name: /add to cart/i }).first().click();
    await page.getByRole('link', { name: /view cart/i }).click();
    await page.getByRole('button', { name: /proceed to checkout/i }).click();

    // Attempt to proceed without filling required fields
    const continueButton = page.getByRole('button', { name: /continue/i }).first();
    await continueButton.click();

    // Verify validation error appears
    await expect(page.getByText(/this field is required/i)).toBeVisible();

    // Fill first name field
    await page.getByLabel(/first name/i).fill('Jane');

    // Verify error persists for other required fields
    await continueButton.click();
    await expect(page.getByText(/this field is required/i)).toBeVisible();

    // Complete all required fields
    await page.getByLabel(/last name/i).fill('Smith');
    await page.getByLabel(/street address/i).fill('456 Oak Ave');
    await page.getByLabel(/city/i).fill('Los Angeles');
    await page.getByLabel(/state/i).fill('CA');
    await page.getByLabel(/zip code/i).fill('90001');

    // Proceed to next step
    await continueButton.click();

    // Verify we moved to shipping selection
    await expect(page.getByRole('heading', { name: /shipping/i })).toBeVisible();

    // Select shipping method
    await page.getByRole('radio', { name: /express shipping/i }).click();
    await page.getByRole('button', { name: /continue/i }).nth(1).click();

    // Verify we moved to payment
    await expect(page.getByRole('heading', { name: /payment/i })).toBeVisible();

    // Fill payment details
    await page.getByLabel(/card number/i).fill('5555555555554444');
    await page.getByLabel(/expiration date/i).fill('06/26');
    await page.getByLabel(/cvv/i).fill('456');

    // Proceed to review
    await page.getByRole('button', { name: /continue/i }).nth(2).click();
    await expect(page.getByRole('heading', { name: /review/i })).toBeVisible();

    // Place order
    await page.getByRole('button', { name: /place order/i }).click();

    // Verify successful completion
    await expect(page.getByText(/thank you for your order/i)).toBeVisible({ timeout: 10000 });
  });

  test('should maintain state across async checkout steps', async () => {
    // Add multiple items
    const addToCartButtons = page.getByRole('button', { name: /add to cart/i });
    await addToCartButtons.first().click();
    await page.waitForTimeout(500);
    await addToCartButtons.nth(1).click();

    // Navigate to cart
    await page.getByRole('link', { name: /view cart/i }).click();

    // Verify both items are in cart
    const cartItems = page.getByRole('row', { name: /product/i });
    await expect(cartItems).toHaveCount(2);

    // Proceed to checkout
    await page.getByRole('button', { name: /proceed to checkout/i }).click();

    // Fill shipping info
    await page.getByLabel(/first name/i).fill('Alice');
    await page.getByLabel(/last name/i).fill('Johnson');
    await page.getByLabel(/street address/i).fill('789 Pine Rd');
    await page.getByLabel(/city/i).fill('Chicago');
    await page.getByLabel(/state/i).fill('IL');
    await page.getByLabel(/zip code/i).fill('60601');

    // Move to shipping
    await page.getByRole('button', { name: /continue/i }).first().click();
    await page.getByRole('radio', { name: /overnight shipping/i }).click();

    // Move to payment
    await page.getByRole('button', { name: /continue/i }).nth(1).click();
    await page.getByLabel(/card number/i).fill('378282246310005');
    await page.getByLabel(/expiration date/i).fill('03/27');
    await page.getByLabel(/cvv/i).fill('789');

    // Review order
    await page.getByRole('button', { name: /continue/i }).nth(2).click();

    // Verify order summary shows correct items and shipping
    await expect(page.getByText(/2 items/i)).toBeVisible();
    await expect(page.getByText(/overnight shipping/i)).toBeVisible();
    await expect(page.getByText(/alice johnson/i)).toBeVisible();

    // Complete order
    await page.getByRole('button', { name: /place order/i }).click();
    await expect(page.getByRole('heading', { name: /order confirmed/i })).toBeVisible({ timeout: 10000 });
  });
});
